from taf.hw.rf_attenuator.devices.jfw.jfw import JFW
from taf.hw.rf_attenuator.exceptions import MultiPortsNotSupported


class JFW50PA505(JFW):
    MAX_SUPPORTED_ATTENUATION = 63
    MIN_SUPPORTED_ATTENUATION = 0

    def set_ports_fading_attenuation(self, set_fading_scenarios, timeout):
        if len(set_fading_scenarios) > 1:
            raise MultiPortsNotSupported

        super(JFW50PA505, self).set_ports_fading_attenuation(set_fading_scenarios, timeout)
